function OverseaManageCafeCattyRankingsDialog:RequestShow()
    local interface = Interfaces.MaidCoffeeCattyRank
    if self.rankType == MaidCoffeeConstants.CoffeeRankType.VipOrderRank then
        interface = Interfaces.MaidCoffeeCatCarRank
    end
    GameUtils.Request(interface, nil, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local responseData = response.data
            self.myRank = responseData.myRank
            self.myScore = responseData.myScore
            self.totalNum = responseData.totalNum
            self.ranks = responseData.ranks

            KTool.SetActive(self.EmptyNode.gameObject, not (#self.ranks > 0))
            KTool.SetActive(self.LayoutListAndMyselef.gameObject, (#self.ranks > 0))
            if #self.ranks > 0 then
                if self.LoopView then
                    if not self.LoopView.IsListViewInit then
                        self.LoopView:InitListView(#self.ranks, Bind(self, self.OnRefreshCellIndex))
                        self.LoopView:UpdateDisplayItemCount(ItemCell)
                    else
                        GameUtils.ReloadData(self.LoopView, #self.ranks)
                    end
                end
            end

            self:RefreshSelfShow()
            KTool.SetActive(self.Root.gameObject,true)
        end
    end)
end

function OverseaManageCafeCattyRankingsDialog:RefreshSelfShow()
    if self.myRankEnv then
        self.myRankEnv:RefreshSelfShow(self.myRank, self.myScore, self.totalNum,self.rankType)
    end
end

function OverseaManageCafeCattyRankingsDialog:OnRefreshCellIndex(listView, index)
    if index < 0 or index >= #self.ranks then
        return
    end
    local cell = listView:NewListViewItem(ItemCell)
    local tableCellEnv = CfUtils.GetLuaScr(cell, RankCellPath)
    tableCellEnv:RefreshShow(self.ranks[index + 1], false,self.rankType)
    if listView.DisplayItemNumber < listView.DisplayItemCount then
        tableCellEnv:PlayDelayAnimByShow(listView.DisplayItemNumber)
        listView.DisplayItemNumber = listView.DisplayItemNumber + 1
    else
        tableCellEnv:PlayAnimByIdle()
    end
    SetListViewAction()
    return cell
end

